#!/usr/bin/env node
/**
 * DokuWiki Direct MCP Server (stdio)
 *
 * A lightweight, zero-dependency MCP server that connects directly to a
 * DokuWiki instance running the MCP plugin. Replaces mcp-remote for
 * environments with self-signed SSL certificates where Node.js fetch/undici
 * ignores NODE_TLS_REJECT_UNAUTHORIZED.
 *
 * Usage:
 *   node dokuwiki-mcp-server.mjs
 *
 * Environment variables:
 *   DOKUWIKI_URL    - MCP plugin endpoint URL (required)
 *                     e.g. https://wiki.example.com/lib/plugins/mcp/mcp.php
 *   DOKUWIKI_TOKEN  - Bearer token for authentication (required)
 *   DOKUWIKI_SKIP_TLS_VERIFY - Set to "1" to skip TLS certificate verification
 *                               (default: "0")
 *
 * @license MIT
 * @see https://www.dokuwiki.org/plugin:mcp
 */

// Handle TLS before any imports that might trigger connections
if (process.env.DOKUWIKI_SKIP_TLS_VERIFY === '1') {
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0';
}

import { createInterface } from 'readline';

const ENDPOINT = process.env.DOKUWIKI_URL;
const TOKEN = [REDACTED];

if (!ENDPOINT) {
  console.error('Error: DOKUWIKI_URL environment variable is required');
  console.error('Example: https://wiki.example.com/lib/plugins/mcp/mcp.php');
  process.exit(1);
}

if (!TOKEN) {
  console.error('Error: DOKUWIKI_TOKEN environment variable is required');
  console.error('Generate a token in DokuWiki Admin > MCP Plugin configuration');
  process.exit(1);
}

// Cache tools list from upstream server
let cachedTools = null;

/**
 * Call the upstream DokuWiki MCP endpoint
 */
async function callUpstream(method, params = {}) {
  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${TOKEN}`,
    },
    body: JSON.stringify({ jsonrpc: '2.0', method, id: 1, params }),
  });

  if (!res.ok) {
    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
  }

  const data = await res.json();
  if (data.error) {
    throw new Error(data.error.message || JSON.stringify(data.error));
  }
  return data.result;
}

/**
 * Fetch and cache the tools list from the upstream server
 */
async function getToolsList() {
  if (!cachedTools) {
    const result = await callUpstream('tools/list');
    cachedTools = result.tools;
  }
  return cachedTools;
}

/**
 * Send a JSON-RPC response to stdout
 */
function sendResponse(id, result) {
  process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id, result }) + '\n');
}

/**
 * Send a JSON-RPC error to stdout
 */
function sendError(id, code, message) {
  process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id, error: { code, message } }) + '\n');
}

/**
 * Handle an incoming JSON-RPC message
 */
async function handleMessage(raw) {
  let msg;
  try {
    msg = JSON.parse(raw);
  } catch {
    return; // Ignore malformed messages
  }

  const { id, method, params } = msg;

  try {
    switch (method) {
      case 'initialize': {
        // Verify upstream connectivity on first connection
        let upstreamInfo;
        try {
          upstreamInfo = await callUpstream('initialize', params);
        } catch (err) {
          sendError(id, -32603, `Cannot reach DokuWiki: ${err.message}`);
          return;
        }

        sendResponse(id, {
          protocolVersion: '2024-11-05',
          capabilities: { tools: { listChanged: false } },
          serverInfo: {
            name: upstreamInfo.serverInfo?.name || 'DokuWiki Direct MCP',
            version: upstreamInfo.serverInfo?.version || 'unknown',
          },
          instructions: upstreamInfo.instructions || 'Access and interact with a DokuWiki instance.',
        });
        break;
      }

      case 'notifications/initialized':
      case 'notifications/cancelled':
      case 'ping':
        if (id !== undefined) sendResponse(id, {});
        break;

      case 'tools/list': {
        const tools = await getToolsList();
        sendResponse(id, { tools });
        break;
      }

      case 'tools/call': {
        const result = await callUpstream('tools/call', params);
        sendResponse(id, result);
        break;
      }

      default:
        if (id !== undefined) {
          sendError(id, -32601, `Method not found: ${method}`);
        }
    }
  } catch (err) {
    if (id !== undefined) {
      sendError(id, -32603, err.message);
    }
  }
}

// stdio JSON-RPC transport
const rl = createInterface({ input: process.stdin });
rl.on('line', (line) => {
  if (line.trim()) handleMessage(line.trim());
});
rl.on('close', () => process.exit(0));
